const items = $input.all();
const config = $('OH: CODE Global Config').first().json;
const payload = typeof config.payload === 'string'
  ? JSON.parse(config.payload)
  : config.payload;

const close_previous   = payload.close_previous ?? true;
const previous_summary = payload.previous_summary || '✓ Выбрано: —';

if (!items.length || !items[0].json.log_id) {
  return [{ json: { found: false, log_id: null, message_id: null, close_previous, previous_summary } }];
}

return [{ json: {
  found:      true,
  log_id:     items[0].json.log_id,
  message_id: items[0].json.message_id,
  close_previous,
  previous_summary,
}}];

const config = $('OH: CODE Global Config').first().json;
const { template_name, data } = config.payload;

const tmpl = config.ADMIN_TEMPLATES[template_name];
let text;

if (typeof tmpl === 'function') {
  text = tmpl(data || {});
} else if (typeof tmpl === 'string') {
  text = tmpl;
  for (const [k, v] of Object.entries(data || {})) {
    text = text.replaceAll(`{${k}}`, String(v));
  }
} else {
  text = '';
}

return [{
  json: {
    request_body: {
      chat_id: Number(config.ADMIN_CHAT_ID),
      text,
      format: 'html',
    }
  }
}];

const config  = $('OH: CODE Global Config').first().json;
const session = $('OH: PG SELECT Session').first().json;
const payload = typeof config.payload === 'string'
  ? JSON.parse(config.payload)
  : config.payload;

const next_step    = payload.next_step;
const dynamic_vars = payload.dynamic_vars || {};

// Какой шаг реально записать в current_step (help/resume не двигают FSM)
const step_to_persist = payload.skip_step_update
  ? session.current_step
  : next_step;

// Текст: опциональный префикс (resume) + текст целевого шага
const prefix = payload.prefix_key ? (config.TXT[payload.prefix_key] + '\n\n') : '';
let text = prefix + (config.TXT[next_step] || '');

// Резолв ключей ERROR_TXT+ перенос строки
if (dynamic_vars.error_text) {
  const resolved = config.ERROR_TXT[dynamic_vars.error_text] ?? '';
  dynamic_vars.error_text = resolved ? resolved + '\n\n' : '';
}
dynamic_vars.error_text  = dynamic_vars.error_text  ?? '';

// Перенос строки после status_text
const rawStatus = dynamic_vars.status_text ?? '';
dynamic_vars.status_text = rawStatus ? rawStatus + '\n\n' : ''

// Подстановка переменных
for (const [k, v] of Object.entries(dynamic_vars)) {
  text = text.replaceAll(`{${k}}`, String(v));
}

const keyboardOverride = payload.keyboard_override || null;
let keyboard = keyboardOverride
  ? keyboardOverride                // уже { buttons: [[...]] }, обёртка не нужна
  : (config.KEYBOARDS[next_step] || null);
// Кнопка "В главное меню" на экранах с ошибкой (только после принятия политики)
if (dynamic_vars.error_text && session.user_id) {
  const navButton = [{ text: "↩️ В главное меню", type: "callback", payload: "nav_menu", intent: "default" }];
  if (keyboard && keyboard.buttons) {
    keyboard = { buttons: [...keyboard.buttons, [navButton[0]]] };
  } else {
    keyboard = { buttons: [[navButton[0]]] };
  }
}

const chat_id  = Number(session.last_chat_id);  // MAX API ожидает number

const attachments = keyboard
  ? [{ type: 'inline_keyboard', payload: { buttons: keyboard.buttons } }]
  : [];

return [{
  json: {
    next_step,
    step_to_persist,
    session_id:   config.session_id,
    max_user_id:  session.max_user_id,
    chat_id,
    has_keyboard: keyboard !== null,
    request_body: {
      text,
      format: 'html',
      attachments,
    },
  }
}];
